16	package io.github.microcks.util.tracing;
17	
18	import io.opentelemetry.api.common.AttributeKey;
19	import io.opentelemetry.api.common.Attributes;
20	import io.opentelemetry.api.common.AttributesBuilder;
21	import io.opentelemetry.api.trace.Span;
22	import io.opentelemetry.api.trace.SpanContext;
23	
24	/**
25	 * Utility class for managing tracing functionality. This class provides constants and methods to enable explain tracing
26	 * in the current context.
27	 *
28	 * @author microcks-team
29	 */
30	public final class TraceUtil {
31	
32	   /**
33	    * The attribute key used to mark spans for explain tracing. When this attribute is set to true on a span, the span
34	    * will be captured by the CustomExplainTraceProcessor and stored in the SpanStorageService.
35	    */
36	   public static final AttributeKey<Boolean> EXPLAIN_TRACE_ATTRIBUTE = AttributeKey.booleanKey("explain-trace");
37	
38	   /**
39	    * Private constructor to prevent instantiation of utility class.
40	    */
41	   private TraceUtil() {
42	      throw new UnsupportedOperationException("Utility class cannot be instantiated");
43	   }
44	
45	   /**
46	    * Enables explain tracing for the current span context. This method adds the explain-trace attribute to the current
47	    * active span, marking it for capture and storage by the tracing infrastructure. If there is no active span in the
48	    * current context, this method will have no effect
49	    *
50	    * @return true if explain tracing was successfully enabled on the current span, false if there was no active span or
51	    *         if the operation failed
52	    */
53	   public static boolean enableExplainTracing() {
54	      Span currentSpan = Span.current();
55	
56	      if (currentSpan.getSpanContext() == null || !currentSpan.getSpanContext().isValid()) {
57	         // No current span available, cannot enable explain tracing
58	         return false;
59	      }
60	
61	      try {
62	         // Add the explain-trace attribute to the current span
63	         currentSpan.setAttribute(EXPLAIN_TRACE_ATTRIBUTE, true);
64	         return true;
65	      } catch (Exception e) {
66	         // Log the error but don't throw to avoid disrupting application flow
67	         // In a real application, you might want to use a proper logger here
68	         System.err.println("Failed to enable explain tracing: " + e.getMessage());
69	         return false;
70	      }
71	   }
72	
73	   /**
74	    * Builder Wrapper enforcing specific attributes on an event. An event has a message attribute which is used as the
75	    * event name in tracing UIs.
76	    */
77	   public static AttributesBuilder explainSpanEventBuilder(String message) {
78	      return Attributes.builder().put("message", message);
79	   }
80	
81	}
