16	package io.github.microcks.util.otel;
17	
18	import io.github.microcks.service.SpanStorageService;
19	import io.github.microcks.util.tracing.TraceUtil;
20	import io.opentelemetry.api.common.AttributeKey;
21	import io.opentelemetry.context.Context;
22	import io.opentelemetry.sdk.trace.ReadWriteSpan;
23	import io.opentelemetry.sdk.trace.ReadableSpan;
24	import io.opentelemetry.sdk.trace.SpanProcessor;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.stereotype.Component;
28	
29	import javax.annotation.Nonnull;
30	import java.util.Map;
31	
32	/**
33	 * A custom SpanProcessor that delegates span storage to SpanStorageService. This processor filters and forwards
34	 * relevant spans to the storage service for collection and retrieval.
35	 *
36	 */
37	@Component
38	public class CustomExplainTraceProcessor implements SpanProcessor {
39	   private static final Logger log = LoggerFactory.getLogger(CustomExplainTraceProcessor.class);
40	
41	   private final SpanStorageService spanStorageService;
42	
43	   public CustomExplainTraceProcessor(SpanStorageService spanStorageService) {
44	      this.spanStorageService = spanStorageService;
45	   }
46	
47	   @Override
48	   public void onStart(@Nonnull Context parentContext, @Nonnull ReadWriteSpan span) {
49	      // Called when a span is started - we don't need to do anything here
50	   }
51	
52	   @Override
53	   public boolean isStartRequired() {
54	      return false; // We don't need to be notified when spans start
55	   }
56	
57	   @Override
58	   public void onEnd(@Nonnull ReadableSpan span) {
59	      // Called when a span ends - delegate to storage service if span matches filter criteria
60	      // if span has attribute explain-trace save it
61	      Map<AttributeKey<?>, Object> attributes = span.toSpanData().getAttributes().asMap();
62	      if (attributes.keySet().stream()
63	            .anyMatch(key -> SpanStorageService.valuesEqualAttr(key, TraceUtil.EXPLAIN_TRACE_ATTRIBUTE))) {
64	         spanStorageService.storeSpan(span);
65	      }
66	   }
67	
68	   @Override
69	   public boolean isEndRequired() {
70	      return true; // We need to be notified when spans end
71	   }
72	
73	   @Override
74	   public void close() {
75	      // Clean up resources when the processor is closed
76	      log.info("TraceSpanProcessor is being closed. Clearing all stored spans.");
77	      spanStorageService.clearAll();
78	   }
79	}
