package io.github.microcks.util.tracing;

import io.github.microcks.event.TraceEvent;

import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.sdk.trace.ReadableSpan;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Utility class providing filtering helpers for trace spans and events. It is used to match live trace events against
 * subscriber-provided criteria and to extract the identifying attributes of a trace from its spans.
 */
public final class SpanFilterUtil {

   /** The attribute key used to carry the service name on a span. */
   private static final AttributeKey<String> SERVICE_NAME = AttributeKey.stringKey("service.name");
   /** The attribute key used to carry the operation name on a span. */
   private static final AttributeKey<String> OPERATION_NAME = AttributeKey.stringKey("operation.name");
   /** The attribute key used to carry the client address on a span. */
   private static final AttributeKey<String> CLIENT_ADDRESS = AttributeKey.stringKey("client.address");

   /**
    * Private constructor to prevent instantiation of utility class.
    */
   private SpanFilterUtil() {
      throw new UnsupportedOperationException("Utility class cannot be instantiated");
   }

   /**
    * Match a value against a pattern that may contain a wildcard.
    *
    * @param pattern The pattern to match against. The special value '*' matches any non-null value. Otherwise the
    *                pattern is interpreted as a full regular expression, falling back to exact string equality if it is
    *                not a valid regex.
    * @param value   The value to test
    * @return true if both are null, false if only one is null, and otherwise whether value matches pattern
    */
   public static boolean matchesWildcard(String pattern, String value) {
      if (pattern == null && value == null) {
         return true;
      }
      if (pattern == null || value == null) {
         return false;
      }
      if ("*".equals(pattern)) {
         return true;
      }
      try {
         return Pattern.matches(pattern, value);
      } catch (PatternSyntaxException e) {
         // Not a valid regex, fall back to exact string equality.
         return pattern.equals(value);
      }
   }

   /**
    * Extract a {@link TraceEvent} from the spans of a trace by reading the 'service.name', 'operation.name' and
    * 'client.address' attributes from the spans.
    *
    * @param traceId The identifier of the trace
    * @param spans   The spans belonging to the trace
    * @return A TraceEvent carrying the extracted attribute values, using null for any attribute that is absent
    */
   public static TraceEvent extractTraceEvent(String traceId, List<ReadableSpan> spans) {
      String service = null;
      String operation = null;
      String clientAddress = null;

      if (spans != null) {
         for (ReadableSpan span : spans) {
            if (service == null) {
               service = span.getAttribute(SERVICE_NAME);
            }
            if (operation == null) {
               operation = span.getAttribute(OPERATION_NAME);
            }
            if (clientAddress == null) {
               clientAddress = span.getAttribute(CLIENT_ADDRESS);
            }
         }
      }

      return new TraceEvent(traceId, service, operation, clientAddress);
   }

   /**
    * Check whether a trace event matches the provided filter criteria. Each of the three criteria is matched against the
    * corresponding event field using {@link #matchesWildcard(String, String)}.
    *
    * @param event         The trace event to test
    * @param service       The service pattern to match against the event's service
    * @param operation     The operation pattern to match against the event's operation
    * @param clientAddress The client address pattern to match against the event's client address
    * @return true if all three criteria match their respective event fields
    */
   public static boolean matchesTraceEvent(TraceEvent event, String service, String operation, String clientAddress) {
      return matchesWildcard(service, event.service()) && matchesWildcard(operation, event.operation())
            && matchesWildcard(clientAddress, event.clientAddress());
   }
}
