import io.github.microcks.event.TraceEvent;
import io.github.microcks.service.SpanStorageService;
import io.github.microcks.util.tracing.SpanFilterUtil;

import io.opentelemetry.sdk.trace.ReadableSpan;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Manages client subscriptions to live trace event streams. Clients register a {@link SseEmitter} together with
 * filtering criteria (service, operation and client address, each supporting wildcards). Whenever new trace data
 * arrives, matching subscribers are notified immediately over Server-Sent Events.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   /** The name of the SSE event carrying a trace update. */
   private static final String TRACE_EVENT_NAME = "trace";
   /** The name of the SSE event used as a keep-alive heartbeat. */
   private static final String HEARTBEAT_EVENT_NAME = "heartbeat";

   private final SpanStorageService spanStorageService;

   /** Thread-safe list of currently registered subscribers. */
   private final List<TraceSubscription> subscriptions = new CopyOnWriteArrayList<>();

   /**
    * Creates a new TraceSubscriptionManager.
    *
    * @param spanStorageService The service used to look up spans for a given trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Register an emitter to receive filtered live trace events. A heartbeat event is sent immediately to confirm the
    * stream is established.
    *
    * @param emitter       The SSE emitter to register
    * @param serviceName   The service name filter (may be a wildcard '*' or a regex)
    * @param operationName The operation name filter (may be a wildcard '*' or a regex)
    * @param clientAddress The client address filter (may be a wildcard '*' or a regex)
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      TraceSubscription subscription = new TraceSubscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      // Remove the subscription once the emitter is done or has failed.
      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> subscriptions.remove(subscription));
      emitter.onError(e -> subscriptions.remove(subscription));

      // Send an immediate heartbeat to confirm the stream is established.
      sendHeartbeat(emitter);
   }

   /**
    * Handle the arrival of new trace data. Retrieves the spans for the trace, extracts the identifying event and
    * notifies every subscriber whose filter criteria match.
    *
    * @param event The trace event signaling new data
    */
   @EventListener
   public void onTraceUpdated(TraceEvent event) {
      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(event.traceId());
      if (spans.isEmpty()) {
         // Nothing to send if there are no spans for this trace.
         return;
      }

      TraceEvent enrichedEvent = SpanFilterUtil.extractTraceEvent(event.traceId(), spans);

      for (TraceSubscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(enrichedEvent, subscription.serviceName(), subscription.operationName(),
               subscription.clientAddress())) {
            sendTraceEvent(subscription.emitter(), enrichedEvent);
         }
      }
   }

   /**
    * Send a heartbeat SSE event to all registered emitters.
    */
   @Scheduled(fixedRate = 30000)
   public void sendHeartbeats() {
      for (TraceSubscription subscription : subscriptions) {
         sendHeartbeat(subscription.emitter());
      }
   }

   /**
    * Send a trace update SSE event to a single emitter, completing the emitter on failure.
    */
   private void sendTraceEvent(SseEmitter emitter, TraceEvent event) {
      try {
         emitter.send(SseEmitter.event().name(TRACE_EVENT_NAME).data(event));
      } catch (IOException e) {
         log.debug("Failed to send trace event to emitter, completing it", e);
         emitter.complete();
      }
   }

   /**
    * Send a heartbeat SSE event to a single emitter, completing the emitter on failure.
    */
   private void sendHeartbeat(SseEmitter emitter) {
      try {
         emitter.send(SseEmitter.event().name(HEARTBEAT_EVENT_NAME).data("ping"));
      } catch (IOException e) {
         log.debug("Failed to send heartbeat to emitter, completing it", e);
         emitter.complete();
      }
   }

   /**
    * Holds a registered emitter together with its filtering criteria.
    *
    * @param emitter       The SSE emitter to notify
    * @param serviceName   The service name filter
    * @param operationName The operation name filter
    * @param clientAddress The client address filter
    */
   private record TraceSubscription(SseEmitter emitter, String serviceName, String operationName,
         String clientAddress) {
   }
